import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.CeYlivdO.js";const h=JSON.parse('{"title":"深入理解C/C++编译与链接技术4：动态库A1：基本讨论之-fPIC","description":"","frontmatter":{"title":"深入理解C/C++编译与链接技术4：动态库A1：基本讨论之`-fPIC`","description":"","tags":["cpp-modern","host","intermediate"],"difficulty":"intermediate","platform":"host","chapter":13,"order":4},"headers":[],"relativePath":"compilation/04-dynamic-libraries-1.md","filePath":"compilation/04-dynamic-libraries-1.md","lastUpdated":null}'),r={name:"compilation/04-dynamic-libraries-1.md"};function c(d,e,l,n,s,p){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="深入理解c-c-编译与链接技术4-动态库a1-基本讨论之-fpic" tabindex="-1">深入理解C/C++编译与链接技术4：动态库A1：基本讨论之<code>-fPIC</code> <a class="header-anchor" href="#深入理解c-c-编译与链接技术4-动态库a1-基本讨论之-fpic" aria-label="Permalink to &quot;深入理解C/C++编译与链接技术4：动态库A1：基本讨论之`-fPIC`&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>这段时间比较累，经常忙着一大堆事情而且准备上班了，这里笔者就这几天终于可以小小的休息一下，继续更新这个系列的相关博客。</p><p>这一篇主要讨论的是动态库的基础内容，特别的，会讨论一下如何制作动态库（重点是Linux，Windows上基本因为MSVC工具链在命令行下使用有点折磨人，而且有大量成熟的构建系统已经覆盖了基本的细节，这里就不拿Windows如何构建动态库详细说明了），以及一些符号修饰签名下的问题。</p><h2 id="如何在linux下创建动态库" tabindex="-1">如何在Linux下创建动态库 <a class="header-anchor" href="#如何在linux下创建动态库" aria-label="Permalink to &quot;如何在Linux下创建动态库&quot;">​</a></h2><p>创建动态库并不麻烦，但是，基本上需要保证着一些步骤：</p><ul><li>所集成的二进制可重定位文件，要求采用位置无关标识进行编译（<code>-fPIC</code>，也就是flags Position Independent Code）</li><li>集成这些PIC二进制可重定位文件，然后传递标识符-shared</li></ul><h2 id="关于-fpic我们聊一聊" tabindex="-1">关于-fPIC我们聊一聊 <a class="header-anchor" href="#关于-fpic我们聊一聊" aria-label="Permalink to &quot;关于-fPIC我们聊一聊&quot;">​</a></h2><p>这个选项很有趣，当然，-shared选项是没啥可说的，只是纯粹的告诉我们的编译器链接动态库而已。但是，为什么这些可重定位文件要求使用位置无关代码进行编译呢？</p><p>在《高级C/C++编译技术》中，抛出了层层递进的三个问题：</p><ul><li>什么是 <code>-fPIC</code>？</li><li>创建动态库（.so）必须使用 <code>-fPIC</code> 吗？</li><li>只有编译动态库时才使用 <code>-fPIC</code> 吗？</li></ul><p>下面，笔者整理一下此书的说辞，结合一点笔者的看法，陈列在下面。</p><h4 id="什么是-fpic" tabindex="-1">什么是<code>-fPIC</code>？ <a class="header-anchor" href="#什么是-fpic" aria-label="Permalink to &quot;什么是`-fPIC`？&quot;">​</a></h4><p><code>-fPIC</code> 的含义是**<code>Position-Independent Code</code>**（生成位置无关代码），换而言之， 编译出来的机器指令 <strong>不依赖固定的加载地址</strong>，在运行时可以被加载到任意内存位置而无需修改代码本身。这很符合我们对动态库功能的感知。我们最后，总是要将一个动态库的符号导出出来给其他第三方的应用程序或者是其他的库进行使用，因此，显然我们不能安排一个绝对的映射地址给这些动态库符号，而是在复用的时候，动态的给予一个偏移地址映射到使用者的进程地址上，这样我们才能实现符号的复用。按照步骤的说：</p><ul><li>-fPIC将会对符号采用 <strong>相对地址</strong> 而不是绝对地址进行映射</li><li>全局变量通过 <strong>GOT（Global Offset Table）</strong> 间接访问</li><li>调用函数通过 <strong>PLT（Procedure Linkage Table）</strong> 跳转</li></ul><hr><h4 id="创建动态库-so-必须使用-fpic-吗" tabindex="-1"><strong>创建动态库（.so）必须使用 <code>-fPIC</code> 吗？</strong> <a class="header-anchor" href="#创建动态库-so-必须使用-fpic-吗" aria-label="Permalink to &quot;**创建动态库（.so）必须使用 `-fPIC` 吗？**&quot;">​</a></h4><p>这个很严肃的说，还真不一定。当然，如果我们说的是今天32位的PC机已经即将绝迹（原谅笔者孤陋寡闻，实在没见过物理的32位PC计算机，单片机倒是玩过一丁点）的话，那我们似乎可以对上述命题持以肯定态度。</p><p>我们思考一下，现代动态库跟共享库都是同义的，多个进程准备共享动态库的代码段。那对于不用的进程，代码被要求可以能放在任意虚拟地址是完全合情合理的。否则loader 必须在装载时对代码做 <strong>重定位修补</strong>，导致代码段无法被共享，加载速度变慢。</p><p>但是X86-64不是，还是可以不使用<code>-fPIC</code>编译出可用的动态库的，但是吧，共享的特性就丢掉了，而且加载速度变慢（加载的时候给所有的符号修正地址）。所以，如果我们严肃的想一想，笔者认为的结论是：</p><blockquote><p><strong>在今天，编译动态库是必须要带有-<code>fPIC</code>符号的，百利无一害（如果很担心轻微的性能损失当我没说，考虑的场景不一致）</strong></p></blockquote><h4 id="fpic是动态库专属的嘛-能否在静态库下使用-fpic" tabindex="-1"><code>-fPIC</code>是动态库专属的嘛？能否在静态库下使用 <code>-fPIC</code>？ <a class="header-anchor" href="#fpic是动态库专属的嘛-能否在静态库下使用-fpic" aria-label="Permalink to &quot;`-fPIC`是动态库专属的嘛？能否在静态库下使用 `-fPIC`？&quot;">​</a></h4><p>显然不是，否则，没有必要让这个标志独立出来。实际上，我们完全可以对准备编译成静态库的可重定位文件一样上<code>-fPIC</code>，这个非常的常见。</p><p>举个例子，笔者手头有一个比较大的工程，他是对每一个子模块都生成一个静态库，然后对这个目录下所有生成的静态库打包生成一个动态库，我们在之前的文章就有讨论过，静态库就是一组可重定位文件的简单集合，所以，很自然的我们就意识到，上述情况我们必须对这个静态库所包含的可重定位文件采用<code>-fPIC</code>标志的编译这些源文件。</p>',24)])])}const C=o(r,[["render",c]]);export{h as __pageData,C as default};
